using namespace std;

class Solution {
public:
    string smallestStringII(string s) {
        string best = s;
        int n = s.size();
        for (int i = 0; i < n; ++i) {
            char min_c = s[i];
            for (int k = i + 1; k < n; ++k) {
                min_c = min(min_c, s[k]);
            }
            if (s[i] > min_c) {
                for (int j = i; j < n; ++j) {
                    if (s[j] == min_c) {
                        string cand = s;
                        reverse(cand.begin() + i, cand.begin() + j + 1);
                        if (cand < best) {
                            best = cand;
                        }
                    }
                }
                return best;
            }
        }
        return best;
    }
};

class Solution {
    public String smallestStringII(String s) {
        String best = s;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            char minC = s.charAt(i);
            for (int k = i + 1; k < n; k++) {
                if (s.charAt(k) < minC) minC = s.charAt(k);
            }
            if (s.charAt(i) > minC) {
                for (int j = i; j < n; j++) {
                    if (s.charAt(j) == minC) {
                        char[] arr = s.toCharArray();
                        int l = i, r = j;
                        while (l < r) {
                            char t = arr[l]; arr[l] = arr[r]; arr[r] = t;
                            l++; r--;
                        }
                        String cand = new String(arr);
                        if (cand.compareTo(best) < 0) {
                            best = cand;
                        }
                    }
                }
                return best;
            }
        }
        return best;
    }
}

var smallestStringII = function(s) {
    let best = s;
    const n = s.length;
    for (let i = 0; i < n; i++) {
        let minC = s[i];
        for (let k = i + 1; k < n; k++) {
            if (s[k] < minC) minC = s[k];
        }
        if (s[i] > minC) {
            for (let j = i; j < n; j++) {
                if (s[j] === minC) {
                    const cand = s.slice(0, i) + s.slice(i, j + 1).split('').reverse().join('') + s.slice(j + 1);
                    if (cand < best) {
                        best = cand;
                    }
                }
            }
            return best;
        }
    }
    return best;
